package com.thingsbook.library;
import android.app.*;import android.content.*;import android.media.session.*;import android.os.*;
/** Explicit opt-in foreground session; notification contains no book title or text. */
public final class ListeningService extends Service {
 private MediaSession session;private android.os.PowerManager.WakeLock wake;private static final int ID=127;
 @Override public void onCreate(){super.onCreate();wake=((android.os.PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(android.os.PowerManager.PARTIAL_WAKE_LOCK,"ThingsBook:PrivateListening");wake.setReferenceCounted(false);NotificationManager manager=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);manager.createNotificationChannel(new NotificationChannel("thingsbook-listening","ThingsBook listening",NotificationManager.IMPORTANCE_LOW));session=new MediaSession(this,"ThingsBook private reading");session.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS|MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);session.setCallback(new MediaSession.Callback(){@Override public void onPlay(){MainActivity.mediaCommand("play");}@Override public void onPause(){MainActivity.mediaCommand("pause");}@Override public void onStop(){MainActivity.mediaCommand("stop");stopSelf();}@Override public void onSeekTo(long position){}},new Handler(getMainLooper()));session.setActive(true);}
 private PendingIntent action(String value,int code){return PendingIntent.getService(this,code,new Intent(this,ListeningService.class).setAction(value),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 @Override public int onStartCommand(Intent intent,int flags,int start){String command=intent==null?null:intent.getAction();if("stop".equals(command)){MainActivity.mediaCommand("stop");stopSelf();return START_NOT_STICKY;}if("toggle".equals(command))MainActivity.mediaCommand("toggle");boolean playing=MainActivity.listeningPlaying();if(playing&&!wake.isHeld())wake.acquire();else if(!playing&&wake.isHeld())wake.release();session.setPlaybackState(new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_STOP).setState(playing?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED,PlaybackState.PLAYBACK_POSITION_UNKNOWN,playing?1:0).build());PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(this,"thingsbook-listening").setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("ThingsBook").setContentText(playing?"Private reading is playing":"Private reading is paused").setContentIntent(open).setVisibility(Notification.VISIBILITY_PRIVATE).setOngoing(true).setOnlyAlertOnce(true).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_pause,"Play / pause",action("toggle",1)).build()).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_pause,"Stop and close",action("stop",2)).build()).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1)).build();startForeground(ID,n);return START_NOT_STICKY;}
 @Override public IBinder onBind(Intent i){return null;}@Override public void onTaskRemoved(Intent i){MainActivity.mediaCommand("stop");stopSelf();}@Override public void onDestroy(){if(wake!=null&&wake.isHeld())wake.release();if(session!=null){session.setActive(false);session.release();}stopForeground(true);MainActivity.foregroundEnded();super.onDestroy();}
}
